<script setup>
import {ref,onUnmounted} from 'vue'
import {memberApi} from './member-service.js'
const input=ref(''),rows=ref([]),password=ref(''),busy=ref(false),message=ref(''),checked=ref(false)
function parse(){try{const emails=new Set();rows.value=input.value.trim().split(/\r?\n/).map((line,i)=>{const [email,name,position,company,...extra]=line.split('\t').map(s=>s.trim());if(extra.length||![email,name,position,company].every(Boolean)||emails.has(email.toLowerCase()))throw Error((i+1)+'행 형식 또는 중복 이메일을 확인해 주세요.');emails.add(email.toLowerCase());return {email,name,position,company,kind:'business',request_id:crypto.randomUUID(),state:'확인 전',error:''}});if(rows.value.length>100)throw Error('한 번에 100명까지 등록할 수 있습니다.');checked.value=false;message.value='명단을 확인한 후 기존 회원 검사를 실행해 주세요.';}catch(e){rows.value=[];message.value=e.message}}
async function preview(){if(busy.value)return;busy.value=true;try{const r=await memberApi({action:'bulk-preview',rows:rows.value.map(({email,name,company,position})=>({email,name,company,position,kind:'business'}))});r.rows.forEach((x,i)=>{rows.value[i].state=x.conflict?'충돌':x.existing?'기존 회원 갱신':'신규 등록';rows.value[i].error=x.conflict||''});checked.value=true;message.value='기존 회원 확인을 마쳤습니다. 충돌 행은 등록하지 않습니다.'}catch(e){message.value=e.message}finally{busy.value=false}}
async function submit(withoutPassword=false){if(busy.value||!checked.value)return;busy.value=true;message.value='등록 중입니다. 이 화면을 닫지 마세요.';try{for(const row of rows.value){if(['완료','충돌'].includes(row.state))continue;row.state='처리 중';try{await memberApi({...row,action:withoutPassword?'provision-profile':'provision',...(!withoutPassword?{password:password.value}:{})});row.state='완료';row.error=''}catch(e){row.state='재확인 필요';row.error=e.message}}message.value='등록 완료 '+rows.value.filter(r=>r.state==='완료').length+'명 / 전체 '+rows.value.length+'명. '+(withoutPassword?'회원정보와 그룹을 서버에 저장했습니다. PMOffice 비밀번호는 설정하지 않았습니다. ':'')+'회원 대상 자동 이메일은 발송하지 않습니다.'}finally{password.value='';busy.value=false}}
onUnmounted(()=>{password.value='';input.value='';rows.value=[]})
</script>
<template><section class="member-panel"><h2>기업 회원 일괄 등록</h2><p>이메일 · 이름 · 직함 · 소속을 탭으로 구분해 한 줄에 한 명씩 입력합니다. 등록 대상 기업: 한국철도공사, 샬롬엔지니어링, 투아이시스, 알에프컴, KTL, 국립한국교통대학교.</p><p>각 회원을 공통 Korail 그룹과 기업 그룹에 포함합니다. 공통 그룹은 전체 읽기, 기업 그룹은 배정 작업 편집 권한을 갖습니다. Google 비밀번호는 변경하지 않습니다.</p><div class="member-form"><label>등록 명단<textarea v-model="input" rows="8" :disabled="busy" autocomplete="off"></textarea></label><button @click="parse" :disabled="busy||!input.trim()">명단 확인</button><button @click="preview" :disabled="busy||!rows.length">기존 회원 검사</button></div><div style="overflow-x:auto"><table v-if="rows.length"><thead><tr><th>이름</th><th>직함</th><th>이메일</th><th>소속</th><th>상태</th></tr></thead><tbody><tr v-for="r in rows" :key="r.request_id"><td>{{r.name}}</td><td>{{r.position}}</td><td>{{r.email}}</td><td>{{r.company}}</td><td>{{r.state}}<span v-if="r.error"> · {{r.error}}</span></td></tr></tbody></table></div><div v-if="checked" class="member-form"><button type="button" @click="submit(true)" :disabled="busy||!rows.some(r=>!['완료','충돌'].includes(r.state))">{{busy?'등록 중':'비밀번호 없이 회원정보·그룹 등록'}}</button><p>회원정보와 그룹을 서버에 저장하며, 다른 기기에서도 회원 목록을 볼 수 있습니다. PMOffice 비밀번호 설정·변경과 회원 자동 메일 발송은 하지 않습니다.</p></div><form v-if="checked" @submit.prevent="submit(false)" class="member-form"><label>공통 초기 PMOffice 비밀번호<input type="password" v-model="password" minlength="8" maxlength="128" required autocomplete="new-password" :disabled="busy"></label><p>비밀번호는 이번 처리에만 사용하고 처리 후 입력란에서 지웁니다. 가입·초대·비밀번호 안내 메일은 보내지 않습니다.</p><button class="member-button" :disabled="busy||!rows.some(r=>!['완료','충돌'].includes(r.state))">{{busy?'등록 중':'회원 등록·그룹 연결 실행'}}</button></form><p role="status" aria-live="polite">{{message}}</p></section></template>
